CROP_KNOWLEDGE = [
    # Rice
    {"id": "rice_001", "content": "Rice (paddy) is a Kharif crop sown June-July and harvested October-December. Requires 25°C-35°C temperature and 100-150cm annual rainfall. Clay loam soil with pH 5.5-6.5 is ideal.", "tags": ["rice", "sowing", "soil", "climate"]},
    {"id": "rice_002", "content": "Rice blast is a major fungal disease causing diamond-shaped lesions on leaves. Control with tricyclazole 0.1% spray or carbendazim 0.1% at first sign. Use resistant varieties like IR-64, Pusa Basmati.", "tags": ["rice", "disease", "fungal", "blast", "control"]},
    {"id": "rice_003", "content": "Brown plant hopper (BPH) is a serious rice pest causing 'hopper burn'. Use neem oil 2% or imidacloprid 0.05% spray. Maintain 2-5cm water depth and avoid excess nitrogen.", "tags": ["rice", "pest", "bph", "insect", "control"]},
    {"id": "rice_004", "content": "Rice requires 120-150kg nitrogen per hectare. Apply 50% N as basal, 25% at tillering, 25% at panicle initiation. Use DAP 60kg/ha and MOP 40kg/ha for phosphorus and potassium.", "tags": ["rice", "fertilizer", "nitrogen", "nutrition"]},
    {"id": "rice_005", "content": "Rice blast (Pyricularia oryzae): Diamond-shaped lesions with gray centers on leaves, nodes, and panicles. Severe in high humidity >90% and temperatures 25-28°C. Prevent with seed treatment (tricyclazole 2g/kg seed).", "tags": ["rice", "disease", "blast", "symptoms", "prevention"]},
    {"id": "rice_006", "content": "Bacterial leaf blight (Xanthomonas oryzae) causes yellow-to-white wavy lesions along leaf veins. Seedling wilting and yield loss up to 60%. Spray streptocycline 200ppm + copper oxychloride 0.3%.", "tags": ["rice", "disease", "bacterial", "blight", "control"]},
    {"id": "rice_007", "content": "Sheath blight (Rhizoctonia solani): Oval-to-irregular green-gray lesions on leaf sheaths. Prevalent in dense canopy with high humidity. Apply validamycin 3L/ha or propiconazole 0.1% at boot leaf stage.", "tags": ["rice", "disease", "sheath blight", "fungal", "control"]},
    {"id": "rice_008", "content": "Rice stem borer: Dead heart in vegetative stage, white earhead in reproductive stage. Use carbofuran 3G granules 33kg/ha at 15-20 days after transplanting. Install pheromone traps at 12/ha.", "tags": ["rice", "pest", "stem borer", "insect", "management"]},

    # Wheat
    {"id": "wheat_001", "content": "Wheat is a Rabi crop sown October-December and harvested March-April. Optimal temperature 15°C-25°C with cool winters. Well-drained loam soil pH 6.0-7.5 is ideal.", "tags": ["wheat", "sowing", "soil", "climate"]},
    {"id": "wheat_002", "content": "Wheat rust (yellow/brown/black): Yellow rust shows yellow stripes on leaves, brown rust has circular brown pustules, black rust appears on stems. Control with propiconazole 0.1% or tebuconazole 0.1%. Resistant varieties: HD-2967, PBW-343.", "tags": ["wheat", "disease", "rust", "fungal", "control"]},
    {"id": "wheat_003", "content": "Wheat requires 120-150kg N, 60kg P2O5, 40kg K2O per hectare. Apply full P&K + half N as basal, remaining N at crown root initiation (21 DAS) and tillering (45 DAS).", "tags": ["wheat", "fertilizer", "nitrogen", "nutrition"]},
    {"id": "wheat_004", "content": "Wheat aphid: Colonies on leaves, stems, and ears causing stunted growth. Spray dimethoate 0.05% or imidacloprid 0.05% when threshold of 5-10 aphids per tiller is crossed. Conserve natural enemies like ladybird beetles.", "tags": ["wheat", "pest", "aphid", "insect", "control"]},
    {"id": "wheat_005", "content": "Loose smut of wheat replaces grain heads with black powdery mass of spores. Treat seeds with carboxin 0.2% or vitavax 2.5g/kg seed. Use certified disease-free seed.", "tags": ["wheat", "disease", "smut", "seed treatment", "prevention"]},
    {"id": "wheat_006", "content": "Wheat requires 4-6 irrigations: crown root initiation (21 DAS), tillering (45 DAS), jointing (60 DAS), flowering (80 DAS), milking (95 DAS), and grain filling (110 DAS). Critical stages: crown root initiation and flowering.", "tags": ["wheat", "irrigation", "water", "critical stages"]},

    # Maize
    {"id": "maize_001", "content": "Maize is grown in both Kharif and Rabi seasons. Requires 20°C-30°C temperature and 50-100cm rainfall. Well-drained sandy loam with pH 5.5-7.0.", "tags": ["maize", "sowing", "climate", "soil"]},
    {"id": "maize_002", "content": "Fall armyworm (Spodoptera frugiperda) is a major maize pest. Young larvae feed on whorl leaves causing window-pane damage. Spray emamectin benzoate 0.4g/L or spinetoram 0.5ml/L. Apply neem cake 250kg/ha at sowing.", "tags": ["maize", "pest", "fall armyworm", "control", "insect"]},
    {"id": "maize_003", "content": "Maize requires 150-200kg N, 60-80kg P2O5, 60-80kg K2O per hectare. Apply 1/3 N + full P&K at sowing, 1/3 N at knee-high stage (30 DAS), 1/3 N at tasseling (55 DAS). Zinc deficiency causes white bud — apply ZnSO4 25kg/ha.", "tags": ["maize", "fertilizer", "nutrition", "zinc"]},
    {"id": "maize_004", "content": "Turcicum leaf blight of maize: Elliptical gray-green lesions that coalesce causing leaf drying. Manage with mancozeb 0.25% spray at first appearance. Grow resistant hybrids like PMH-1.", "tags": ["maize", "disease", "leaf blight", "fungal", "control"]},
    {"id": "maize_005", "content": "Maize stem borer (Chilo partellus): Dead heart symptom in young plants. Apply carbofuran 3G granules 8kg/ha in whorl at 15-20 DAS. Use trichogramma cards at 50,000/ha for biological control.", "tags": ["maize", "pest", "stem borer", "biological control"]},

    # Sugarcane
    {"id": "sugarcane_001", "content": "Sugarcane is planted October-February (spring) and September-October (autumn). Requires 25°C-35°C and 100-175cm rainfall. Deep well-drained loam with pH 6.5-7.5.", "tags": ["sugarcane", "sowing", "climate", "soil"]},
    {"id": "sugarcane_002", "content": "Red rot (Colletotrichum falcatum): Most destructive sugarcane disease. Causes reddened internal tissue with white patches crosswise. Use disease-free setts, treat with carbendazim 0.1% for 10 minutes. Resistant varieties: Co-0238, Co-05011.", "tags": ["sugarcane", "disease", "red rot", "fungal", "management"]},
    {"id": "sugarcane_003", "content": "Sugarcane requires 250-300kg N, 60-80kg P2O5, 60-80kg K2O per hectare. Apply full P&K + 50% N at planting, 25% N at tillering (60 DAP), 25% N at grand growth (120 DAP).", "tags": ["sugarcane", "fertilizer", "nutrition"]},
    {"id": "sugarcane_004", "content": "Sugarcane early shoot borer causes dead hearts 30-50 days after planting. Apply carbofuran 3G 33kg/ha in soil at planting time. Remove and destroy dead hearts.", "tags": ["sugarcane", "pest", "shoot borer", "control"]},

    # Cotton
    {"id": "cotton_001", "content": "Cotton is a Kharif crop sown April-June. Requires 20°C-35°C and 60-100cm rainfall. Black cotton soil (regur) with pH 6.0-8.0 is ideal.", "tags": ["cotton", "sowing", "climate", "soil"]},
    {"id": "cotton_002", "content": "Pink bollworm (Pectinophora gossypiella): Most destructive cotton pest. Larvae bore into bolls, feed on seeds, causing rosette flowers. Use Bt cotton, install pheromone traps 5/ha, spray neem oil 5% at flowering.", "tags": ["cotton", "pest", "pink bollworm", "bt", "control"]},
    {"id": "cotton_003", "content": "Cotton requires 100-120kg N, 50-60kg P2O5, 50-60kg K2O per hectare. Apply 50% N + full P&K at sowing, 25% N at square formation (40 DAS), 25% N at flowering (70 DAS).", "tags": ["cotton", "fertilizer", "nutrition"]},
    {"id": "cotton_004", "content": "Cotton leaf curl virus: Upward curling of leaves with vein thickening. Transmitted by whitefly. Control whitefly with imidacloprid 0.05% and remove infected plants. Resistant varieties: Anjali, Vikram.", "tags": ["cotton", "disease", "leaf curl", "virus", "whitefly"]},
    {"id": "cotton_005", "content": "American bollworm (Helicoverpa armigera): Feeds on squares, flowers, and bolls causing heavy shedding. Spray emamectin benzoate 1g/10L or indoxacarb 1ml/L at egg stage. Bt cotton provides effective control.", "tags": ["cotton", "pest", "bollworm", "helicoverpa", "control"]},

    # Groundnut
    {"id": "groundnut_001", "content": "Groundnut is a Kharif crop. Requires 25°C-30°C and 50-75cm rainfall. Well-drained sandy loam with pH 6.0-7.0. Cannot tolerate waterlogging.", "tags": ["groundnut", "sowing", "climate", "soil"]},
    {"id": "groundnut_002", "content": "Tikka disease (Cercospora leaf spot): Circular brown spots with yellow halo on leaves causing defoliation. Spray mancozeb 0.2% or chlorothalonil 0.2% at 15-day intervals starting 30 DAS.", "tags": ["groundnut", "disease", "tikka", "leaf spot", "control"]},
    {"id": "groundnut_003", "content": "Groundnut requires 20-25kg N, 40-60kg P2O5, 50-70kg K2O per hectare. Apply full dose as basal. Also apply gypsum 500kg/ha at pegging stage for pod development.", "tags": ["groundnut", "fertilizer", "gypsum", "nutrition"]},
    {"id": "groundnut_004", "content": "Groundnut stem rot (Sclerotium rolfsii): White mycelial growth on stems near soil line, wilting, and pod rot. Avoid excessive moisture, practice crop rotation with cereals, apply Trichoderma viride 2.5kg/ha in soil.", "tags": ["groundnut", "disease", "stem rot", "biological control"]},

    # General pest management
    {"id": "general_pest_001", "content": "Integrated Pest Management (IPM): Combine biological, cultural, mechanical, and chemical methods. Use resistant varieties, conserve natural enemies, practice crop rotation, monitor with pheromone traps, spray only at economic threshold levels.", "tags": ["general", "pest", "ipm", "integrated", "management"]},
    {"id": "general_pest_002", "content": "Biological control agents: Trichogramma (egg parasitoid) for lepidopteran pests, Chrysoperla (green lacewing) for aphids, Neem-based products for general pests. Pseudomonas fluorescens for soil-borne disease suppression.", "tags": ["general", "biological control", "predators", "parasitoids"]},
    {"id": "general_pest_003", "content": "Natural enemies of crop pests: Ladybird beetles (aphids), Chrysoperla (aphids, eggs), spiders (general predators), Trichogramma (egg parasitoid), Braconid wasps (caterpillars). Conserve through reduced pesticide use and flowering hedges.", "tags": ["general", "natural enemies", "beneficial insects", "conservation"]},

    # Soil management
    {"id": "soil_001", "content": "Soil testing every 2-3 years is essential. Collect samples from 15cm depth at 10 locations per acre, mix thoroughly, and submit 500g to soil testing lab. Test for pH, EC, organic carbon, N, P, K, S, Zn, Fe, Mn, Cu, B.", "tags": ["soil", "testing", "sampling", "nutrients"]},
    {"id": "soil_002", "content": "Organic matter management: Apply well-decomposed FYM 10-15 tons/ha or vermicompost 5 tons/ha annually. Green manuring with dhaincha or sunn hemp adds 50-80kg N/ha. Incorporate crop residues after harvest.", "tags": ["soil", "organic matter", "fym", "vermicompost", "green manure"]},
    {"id": "soil_003", "content": "Soil pH management: Acidic soil (pH <5.5) requires liming — apply 2-4 tons/ha lime. Alkaline soil (pH >8.5) needs gypsum 5-10 tons/ha plus organic matter. Most crops prefer pH 6.0-7.5 for optimal nutrient availability.", "tags": ["soil", "pH", "lime", "gypsum", "amendment"]},
    {"id": "soil_004", "content": "Micronutrient deficiencies: Zn — white/yellow interveinal chlorosis (apply ZnSO4 25kg/ha); Fe — interveinal chlorosis on young leaves (FeSO4 spray 0.5%); B — hollow stems, poor fruit set (borax 10kg/ha); Mn — gray specks on leaves (MnSO4 0.5% spray).", "tags": ["soil", "micronutrient", "deficiency", "zinc", "iron", "boron"]},
    {"id": "soil_005", "content": "Crop rotation principles: Rotate deep-rooted with shallow-rooted crops, legumes with non-legumes, cereals with pulses. Avoid growing same crop family in consecutive seasons to break pest and disease cycles.", "tags": ["soil", "crop rotation", "principles", "management"]},

    # Water management
    {"id": "water_001", "content": "Drip irrigation saves 40-60% water compared to flood irrigation. Ideal for row crops like sugarcane, vegetables, cotton. Combine with fertigation for 25% higher fertilizer use efficiency. Install filter and pressure regulator.", "tags": ["water", "drip", "irrigation", "fertigation", "efficiency"]},
    {"id": "water_002", "content": "Sprinkler irrigation suitable for closely spaced crops like wheat, pulses, vegetables. Saves 30-40% water. Wind speed >15 km/h reduces uniformity. Best for sandy soils with high infiltration rate.", "tags": ["water", "sprinkler", "irrigation", "efficiency"]},
    {"id": "water_003", "content": "Critical crop growth stages for irrigation: Rice — panicle initiation and flowering; Wheat — crown root initiation and flowering; Maize — tasseling and grain filling; Sugarcane — tillering and grand growth; Cotton — flowering and boll development.", "tags": ["water", "irrigation", "critical stages", "crop"]},
    {"id": "water_004", "content": "Rainwater harvesting: Construct farm ponds (1% of farm area for every 100mm rainfall). Use lined ponds in high-permeability soils. Store water for protective irrigation during dry spells. Check dam construction in watershed.", "tags": ["water", "rainwater", "harvesting", "pond", "conservation"]},

    # Weather-based advisories
    {"id": "weather_001", "content": "Heat wave (temp > 40°C): Increase irrigation frequency, apply mulch to conserve soil moisture, provide shade nets for vegetables, spray anti-transpirants. Avoid fertilizer application during heat stress.", "tags": ["weather", "heat", "stress", "management", "irrigation"]},
    {"id": "weather_002", "content": "Heavy rain (>50mm in 24h): Ensure drainage in fields, avoid fertilizer/pesticide application, stake tall plants, harvest mature fruits/vegetables. After rain: drain excess water, check for pest outbreak, apply fungicide if needed.", "tags": ["weather", "rain", "flood", "drainage", "management"]},
    {"id": "weather_003", "content": "Cold wave/frost (temp < 5°C): Irrigate fields before frost night (water releases heat), cover seedlings with polythene/protective covers, spray 0.1% sulfur to protect blossoms. Grow windbreaks on field boundaries.", "tags": ["weather", "cold", "frost", "protection", "management"]},
    {"id": "weather_004", "content": "Drought conditions: Use drought-tolerant varieties, apply mulch 5-10cm thick, practice skip-irrigation, use anti-transpirants like kaolin spray 3%. Postpone transplanting until conditions improve. Foliar spray of 2% urea for stress tolerance.", "tags": ["weather", "drought", "management", "mulch", "conservation"]},
    {"id": "weather_005", "content": "High humidity (>85%): Monitor for fungal disease outbreaks (blight, mildew, rot). Apply preventive fungicide sprays, improve air circulation through proper spacing, avoid overhead irrigation. Delay nitrogen application.", "tags": ["weather", "humidity", "fungal", "disease", "prevention"]},
    {"id": "weather_006", "content": "Wind speed > 20 km/h: Delay spraying operations (drift loss), stake tall crops, check windbreak effectiveness. For fruit orchards, ensure proper staking. Hail nets recommended in hail-prone areas.", "tags": ["weather", "wind", "spray", "protection"]},

    # Fertilizer management
    {"id": "fert_001", "content": "Neem-coated urea (NCU): 15-20% more efficient than prilled urea. Reduces nitrogen loss through leaching and denitrification. Apply NCU 10-12 days before crop requirement stage. Available as 46% N.", "tags": ["fertilizer", "urea", "neem-coated", "efficiency"]},
    {"id": "fert_002", "content": "Bio-fertilizers: Rhizobium (pulses — 200g/10kg seed), Azospirillum (cereals — 5kg/ha), PSB (phosphate solubilizing — 5kg/ha), Azolla (rice — 0.5-1 ton/ha as green manure). Apply near root zone within 24h of mixing.", "tags": ["fertilizer", "biofertilizer", "rhizobium", "azospirillum", "psb"]},
    {"id": "fert_003", "content": "Vermicompost: 1.5-2.5% N, 0.5-1.5% P2O5, 0.5-1.5% K2O. Apply 5 tons/ha. Earthworms (Eisenia fetida) process 1 ton organic waste in 30-45 days. Keep bedding moist (40-50%) and shaded.", "tags": ["fertilizer", "vermicompost", "organic", "earthworms"]},
    {"id": "fert_004", "content": "Fertigation schedule: Inject water-soluble fertilizers through drip system. Common schedule — 1/4 dose at seedling, 1/2 at vegetative growth, 1/4 at reproductive stage. Use 19:19:19 NPK for vegetative stage, 12:61:00 for flowering.", "tags": ["fertilizer", "fertigation", "drip", "schedule"]},
    {"id": "fert_005", "content": "Leaf color chart (LCC) for nitrogen management in rice: Hold LCC on fully expanded top leaf. If color <4, apply 30kg N/ha. If >4, skip. Use every 7-10 days from 14 DAT to flowering. Saves 25-30% N without yield loss.", "tags": ["fertilizer", "nitrogen", "lcc", "rice", "management"]},

    # Vegetables
    {"id": "veg_001", "content": "Tomato: Temperature 20°C-27°C, pH 6.0-6.8. Common diseases: early blight (mancozeb 0.2%), late blight (metalaxyl 0.2%), leaf curl virus (control whitefly with imidacloprid). Stake plants for better fruit quality.", "tags": ["tomato", "vegetable", "disease", "temperature", "management"]},
    {"id": "veg_002", "content": "Brinjal/eggplant: Temperature 22°C-30°C. Shoot and fruit borer is major pest — remove infected shoots, spray emamectin benzoate 1g/10L, use pheromone traps. Practice crop rotation with non-solanaceous crops.", "tags": ["brinjal", "eggplant", "pest", "borer", "management"]},
    {"id": "veg_003", "content": "Chilli: Temperature 20°C-30°C. Major pests: thrips, mites, fruit borer. Diseases: anthracnose (mancozeb + carbendazim), leaf curl (imidacloprid for vector control). Apply FYM 25t/ha + 100:50:50 NPK kg/ha.", "tags": ["chilli", "pepper", "pest", "disease", "management"]},
    {"id": "veg_004", "content": "Onion: Temperature 15°C-25°C (bulbing requires long days). Major pest: thrips (spray dimethoate 0.05%). Diseases: purple blotch (mancozeb 0.2%), downy mildew (metalaxyl 0.2%). Reduce irrigation 15 days before harvest.", "tags": ["onion", "vegetable", "pest", "disease", "management"]},
    {"id": "veg_005", "content": "Okra/ladyfinger: Temperature 25°C-35°C. Yellow vein mosaic virus management: control whitefly vector, remove infected plants, use resistant varieties (Pusa Sawani, Varsha Uphar). Fruit borer: spray cypermethrin 0.05%.", "tags": ["okra", "ladyfinger", "virus", "pest", "management"]},

    # Fruits
    {"id": "fruit_001", "content": "Mango: Temperature 25°C-35°C, pH 5.5-7.5. Major diseases: powdery mildew (dinocap 0.1%), anthracnose (carbendazim 0.1%), mango malformation (deblossoming + NAA spray). Apply FYM 50kg/tree + 1:0.5:1 kg NPK/tree/year.", "tags": ["mango", "fruit", "disease", "management"]},
    {"id": "fruit_002", "content": "Banana: Temperature 25°C-35°C, pH 6.0-7.5. Panama wilt (Fusarium): Use disease-free tissue culture plants, soil drench with carbendazim 0.1%. Sigatoka leaf spot: spray mancozeb 0.2% + tridemorph 0.1%. Apply 300g N + 100g P + 300g K per plant.", "tags": ["banana", "fruit", "disease", "wilt", "management"]},
    {"id": "fruit_003", "content": "Citrus (lemon, orange): Temperature 20°C-35°C. Major disease: citrus canker (bacterial) — spray streptocycline 100ppm + copper oxychloride 0.3%. Major pest: citrus leaf miner (spray imidacloprid 0.05%). Nutrition: 600g N + 200g P + 300g K per tree annually.", "tags": ["citrus", "lemon", "orange", "disease", "pest", "management"]},
    {"id": "fruit_004", "content": "Grape: Temperature 15°C-35°C. Major diseases: downy mildew (metalaxyl 0.2%), powdery mildew (dinocap 0.1%), anthracnose (carbendazim 0.1%). Proper canopy management critical for disease control. Drip irrigation recommended.", "tags": ["grape", "fruit", "disease", "management"]},

    # Pulses
    {"id": "pulse_001", "content": "Pigeonpea (arhar/toor): Kharif crop, 25°C-35°C. Major pest: pod borer (Helicoverpa) — spray emamectin benzoate 0.5g/L at flowering. Major disease: wilt (Fusarium) — use resistant varieties, seed treatment with Trichoderma 4g/kg.", "tags": ["pigeonpea", "arhar", "pulse", "pest", "disease"]},
    {"id": "pulse_002", "content": "Chickpea (gram): Rabi crop, 15°C-25°C. Major disease: wilt and root rot — seed treatment with carbendazim 2g/kg, use resistant varieties. Major pest: pod borer — spray NPV virus 250 LE/ha. Apply 20:50:20 NPK kg/ha.", "tags": ["chickpea", "gram", "pulse", "disease", "pest"]},
    {"id": "pulse_003", "content": "Black gram (urad): Kharif crop, 25°C-35°C. Diseases: yellow mosaic virus — control whitefly vector, use resistant varieties. Leaf spot: spray mancozeb 0.2%. Rhizobium seed treatment for nitrogen fixation.", "tags": ["black gram", "urad", "pulse", "disease", "management"]},

    # Organic farming
    {"id": "organic_001", "content": "Organic farming principles: No synthetic fertilizers or pesticides. Use FYM, vermicompost, green manure, bio-fertilizers for nutrition. Neem, garlic, chilli extracts for pest control. Requires 3-year transition period for certification.", "tags": ["organic", "farming", "principles", "certification"]},
    {"id": "organic_002", "content": "Neem-based pesticides: Neem seed kernel extract (NSKE) 5% — soak 5kg neem powder in 100L water overnight, filter and spray. Effective against aphids, jassids, caterpillars. Azadirachtin disrupts insect molting and feeding.", "tags": ["organic", "neem", "pesticide", "nske", "botanical"]},
    {"id": "organic_003", "content": "Jeevamrit (liquid organic fertilizer): Mix 10kg cow dung + 10L cow urine + 2kg jaggery + 2kg pulse flour + handful soil in 200L water. Stir daily for 7 days. Apply 200L/acre at 15-day intervals. Provides nutrients + beneficial microbes.", "tags": ["organic", "jeevamrit", "liquid", "fertilizer", "preparation"]},
    {"id": "organic_004", "content": "Panchagavya: Mix 5kg cow dung + 3L cow urine + 2L milk + 2L curd + 1L ghee + 3L tender coconut water + 500g jaggery. Ferment 15 days stirring daily. Dilute 3% in water and spray. Boosts growth and immunity.", "tags": ["organic", "panchagavya", "growth promoter", "preparation"]},

    # Seasonal calendars
    {"id": "season_001", "content": "Kharif season (June-October): Sow rice, maize, cotton, groundnut, pigeonpea, soybean, sugarcane at onset of monsoon. Harvest before November. Pests more severe due to high humidity. Plan fungicide sprays preventively.", "tags": ["season", "kharif", "summer", "monsoon", "calendar"]},
    {"id": "season_002", "content": "Rabi season (October-March): Sow wheat, barley, chickpea, mustard, peas, potato after monsoon. Requires irrigation. Harvest March-April. Lower pest pressure but watch for rust in wheat, pod borer in chickpea.", "tags": ["season", "rabi", "winter", "calendar", "irrigation"]},
    {"id": "season_003", "content": "Zaid/Summer season (April-June): Short duration crops: watermelon, muskmelon, cucumber, fodder. High temperature requires frequent irrigation. Mulching essential for moisture conservation. Watch for thrips and mites.", "tags": ["season", "zaid", "summer", "calendar"]},

    # Soil health indicators
    {"id": "soilhealth_001", "content": "Earthworm count: >10 per square foot indicates healthy soil. 5-10 is moderate. <5 means poor soil health needing organic matter improvement. Earthworms improve aeration, drainage, and nutrient cycling.", "tags": ["soil", "health", "earthworm", "indicator"]},
    {"id": "soilhealth_002", "content": "Water infiltration test: Dig a 30cm hole, fill with water. If drained in <10 min — sandy (low water holding). 10-30 min — loamy (ideal). >30 min — clay (drainage issue). Ideal is 15-25 minutes.", "tags": ["soil", "health", "infiltration", "test"]},
    {"id": "soilhealth_003", "content": "Organic carbon: >0.75% is good, 0.5-0.75% medium, <0.5% low. Every 1% increase in OC improves water holding capacity by 6%. Apply FYM 10t/ha annually to maintain OC levels.", "tags": ["soil", "organic carbon", "test", "management"]},

    # Post-harvest
    {"id": "postharvest_001", "content": "Grain storage: Dry grains to <14% moisture. Store in clean, air-tight containers. Use neem leaves (2% w/w) or alum (1% w/w) as natural grain protectant. Fumigate with aluminum phosphide 3g/ton for insect control.", "tags": ["postharvest", "storage", "grain", "protection"]},
    {"id": "postharvest_002", "content": "Fruit ripening: Use ethylene gas (100-150ppm for 24-48h) or ethephon 0.05% dip for uniform ripening. Never use calcium carbide (carcinogenic — banned in India). Store at 10-15°C for extended shelf life.", "tags": ["postharvest", "ripening", "ethylene", "storage", "safety"]},
    {"id": "postharvest_003", "content": "Vegetable storage: Cool immediately after harvest to remove field heat (hydrocooling or forced air cooling). Store leafy vegetables at 0-2°C with 95% RH, root vegetables at 0-2°C with 90% RH. Tomatoes at 12-15°C.", "tags": ["postharvest", "vegetable", "storage", "cooling"]},

    # Market & eNAM (Phase 2: agent market literacy — no price generation)
    {"id": "market_001", "content": "Net realization means the money you keep: mandi modal price minus farmer-borne costs (transport, storage, loading, bagging, handling). A mandi with a higher headline price can leave less in your pocket if transport is high. Compare mandis by net, not headline. Kisan360 ranks mandis by this number; it does not predict future prices.", "tags": ["market", "net realization", "mandi", "economics"]},
    {"id": "market_002", "content": "APMC commission and market fees in Maharashtra are charged to the buyer under APMC Act section 31, not to the farmer. They must not be subtracted from the farmer net. Transport, storage and handling paid by the farmer are the only deductions in net realization.", "tags": ["market", "apmc", "commission", "farmer-borne"]},
    {"id": "market_003", "content": "eNAM (National Agriculture Market) links APMC mandis on one electronic platform so buyers across mandis can bid. It changes where you can sell, not what you are guaranteed. Assay and quality grading decide which bids apply to your lot.", "tags": ["market", "enam", "apmc", "online"]},
    {"id": "market_004", "content": "FPO pooling: when individual lots are below a buyer's minimum quantity, pooling through a Farmer Producer Organisation can unlock larger transport tiers and buyers who do not serve small lots. Compare pooled vs individual net before deciding.", "tags": ["market", "fpo", "pooling", "bulk"]},
    {"id": "market_005", "content": "How to read a mandi price quote: min/max is the range of prices paid that day, modal is the most common price paid. Arrival date is when the quote was observed. Always check source and date — a cached quote describes the past, never a guaranteed future price.", "tags": ["market", "price", "modal", "agmarknet", "provenance"]},

    # Pulses & oilseeds expansion (Phase 2b)
    {"id": "pulse_004", "content": "Soybean is a Kharif oilseed, 20-30C, 60-80cm rain. Rhizobium + PSB seed treatment fixes nitrogen; do not over-apply urea. Major pests: stem fly, girdle beetle, whitefly. Sow on ridges in heavy rain areas. Source: ICAR soybean package.", "tags": ["soybean", "oilseed", "kharif", "pest"]},
    {"id": "pulse_005", "content": "Moong is a short-duration Kharif/Rabi pulse, needs 25-35C. Major disease: yellow mosaic virus (whitefly vector) — rogue infected plants early, use resistant varieties. Rhizobium treatment improves N fixation. Apply 20:40:20 NPK kg/ha at sowing.", "tags": ["moong", "pulse", "virus", "fertilizer"]},
    {"id": "pulse_006", "content": "Mustard is a Rabi oilseed, 15-25C. Major pests: aphid and mustard sawfly — spray dimethoate 0.05% at aphid threshold 5-10 per twig. Disease: white rust and Alternaria blight — spray mancozeb 0.25% at first sign.", "tags": ["mustard", "oilseed", "rabi", "pest", "disease"]},
    {"id": "veg_006", "content": "Potato: Rabi crop, 15-20C, sandy loam pH 5.5-7.0. Late blight (Phytophthora) in cool humid weather — spray metalaxyl + mancozeb immediately at first spots, destroy infected haulms. Source: ICAR-CPRI advisory.", "tags": ["potato", "vegetable", "late blight", "disease"]},
    {"id": "onion_002", "content": "Onion storage: cure bulbs 7-10 days in shade, sort out damaged bulbs, dry to 14% moisture, store in ventilated dark cool place. Avoid stacking >1m. Check weekly for sprouting and rot. Source: NHRDF post-harvest guidance.", "tags": ["onion", "storage", "postharvest"]},
    {"id": "onion_003", "content": "Onion thrips cause silvering of leaves and yield loss. Spray dimethoate 0.05% or spinosad when 10 thrips per plant appear. Purple blotch (Alternaria) in humid weather — spray mancozeb 0.25% at 10-day interval.", "tags": ["onion", "pest", "thrips", "disease"]},

    # Phase 3 expansion: sorghum / bajra / barley / more pulses & vegetables
    {"id": "sorghum_001", "content": "Sorghum (jowar) is a Kharif/Rabi dryland cereal, 25-32C, 40-70cm rain. Sandy to black soil pH 6.0-7.5. Shoot fly and stem borer are key pests — sow early, use resistant varieties, deep plough to expose pupae. Source: ICAR sorghum package.", "tags": ["sorghum", "jowar", "cereal", "pest"]},
    {"id": "sorghum_002", "content": "Sorghum grain mold in humid weather — harvest promptly, dry to 12% moisture before storage. Apply 60:30:30 NPK kg/ha. Intercrop with pigeonpea for soil cover and income stability.", "tags": ["sorghum", "storage", "fertilizer"]},
    {"id": "bajra_001", "content": "Pearl millet (bajra) is a Kharif dryland cereal, 25-35C, 40-60cm rain, sandy soil pH 6.0-7.5. Downy mildew (green ear) — seed treat with metalaxyl 6g/kg. Shoot fly — deep sowing avoidance, 2% neem spray at 15 DAS.", "tags": ["bajra", "millet", "drought", "disease"]},
    {"id": "bajra_002", "content": "Bajra requires 40:20:20 NPK kg/ha (30-40kg N in two splits). Ear head worm — spray emamectin at ear emergence. Residue retention improves in-situ moisture.", "tags": ["bajra", "fertilizer", "pest"]},
    {"id": "barley_001", "content": "Barley is a Rabi cereal like wheat but more drought/salinity tolerant, 12-18C. Aphid and rust are major — use resistant varieties, avoid excess N. Needs 3-4 irrigations at crown root, tillering, flowering and grain filling.", "tags": ["barley", "rabi", "cereal", "irrigation"]},
    {"id": "chickpea_002", "content": "Chickpea sowing: medium black soil, mid-October to mid-November. Rhizobium treatment 200g/10kg seed. Pre-emergence pendimethalin 1.0 kg/ha controls weeds. Harvest at 110-120 DAS when pods turn yellow-brown.", "tags": ["chickpea", "pulse", "sowing", "weeds"]},
    {"id": "urad_002", "content": "Urad (black gram) prefers well-drained loam, 25-35C. Whitefly transmits yellow mosaic — rogue early, spray imidacloprid 0.05% at first vectors. Do not irrigate at flowering if waterlogged.", "tags": ["urad", "pulse", "virus", "whitefly"]},
    {"id": "mung_002", "content": "Moong water management: light irrigation at 20-25 DAS and 40-45 DAS if rain fails. Waterlogging at germination kills seedlings. Staking not needed. Harvest 60-70 days Kharif, 90-110 days Rabi.", "tags": ["moong", "pulse", "irrigation"]},
    {"id": "veg_007", "content": "Cabbage: Rabi, 15-20C. Diamondback moth — spray Bacillus thuringiensis 1g/L or emamectin. Black rot (Xanthomonas) — use disease-free seeds, rotate with non-crucifers 2 years. Source: ICAR vegetable guidance.", "tags": ["cabbage", "vegetable", "pest", "disease"]},
    {"id": "veg_008", "content": "Cauliflower: Rabi, 15-25C. Aphid and diamondback moth control as in cabbage. Boron deficiency causes hollow stem — spray borax 0.1% at curd initiation. Avoid overhead watering to cut Alternaria.", "tags": ["cauliflower", "vegetable", "boron", "pest"]},
    {"id": "veg_009", "content": "Cucumber: Zaid, 22-30C, sandy loam. Fruit fly — bait traps + emamectin at flowering. Powdery mildew — sulfur 0.2% at first white patches. Pick frequently to sustain yield.", "tags": ["cucumber", "vegetable", "fruit fly", "disease"]},
    {"id": "fruit_005", "content": "Pomegranate: 25-35C, pH 5.5-7.0. Bacterial blight (Xanthomonas) — spray streptocycline 100ppm + copper oxychloride 0.3% at first spots. Fruit borer — remove mummified fruits, pheromone traps 5/ha.", "tags": ["pomegranate", "fruit", "disease", "pest"]},
    {"id": "fruit_006", "content": "Papaya: 25-30C, frosts destroy crop. Papaya ring spot virus (aphid vector) — rogue infected plants, control aphids, use resistant varieties. Apply FYM 10kg/plant + 200:250:250g NPK/plant/year in splits.", "tags": ["papaya", "fruit", "virus", "aphid"]},
    {"id": "general_pest_004", "content": "Whitefly (Bemisia tabaci): vectors leaf curl and yellow mosaic in cotton, tomato, chilli, okra. Yellow sticky traps 15/ha catch adults. Spray imidacloprid 0.05% at nymph stage. Remove alternate hosts.", "tags": ["general", "whitefly", "pest", "virus"]},
    {"id": "general_pest_005", "content": "Thrips: spread by wind, damage at hot dry spells. Blue sticky traps, spray spinosad 0.015% or dimethoate 0.05%. Avoid blanket sprays that kill Chrysoperla predators.", "tags": ["general", "thrips", "pest"]},
    {"id": "soil_006", "content": "Saline soil (EC >4 dS/m): apply gypsum 5-10 t/ha, leach with good quality water, grow salt-tolerant crops (barley, cotton, sugarbeet). Subsurface drainage where water table is high. Test EC before sowing.", "tags": ["soil", "salinity", "gypsum", "reclamation"]},
    {"id": "water_005", "content": "Deficit irrigation: apply water at critical stages only and allow soil moisture to fall to 40% available water between irrigations. Mulch 5-10cm reduces evaporation 25-30%. Use tensiometers at 15 and 30 cm to schedule.", "tags": ["water", "irrigation", "deficit", "mulch"]},
    {"id": "weather_007", "content": "Hail storm: sugarcane and cotton lodge — drain water, spray mancozeb 0.25% to cover wounds, earth up stems. Vegetables: harvest what is salvageable, re-sow short-duration crop if loss >50%.", "tags": ["weather", "hail", "damage"]},
    {"id": "fert_006", "content": "DAP (18-46-0): basal for P + starter N. Do not mix DAP with seed in the same drill if soil is dry — germination injury. Band place 5 cm below and beside seed. For top-dressing use urea, not DAP.", "tags": ["fertilizer", "dap", "sowing"]},
    {"id": "organic_005", "content": "Beejamrit (seed treatment slurry): 5kg cow dung + 5L cow urine + 2kg jaggery in 20L water, ferment 24h, mix with seed and shade-dry before sowing. Protects germination in dry sowing.", "tags": ["organic", "beejamrit", "seed"]},
    {"id": "season_004", "content": "Monsoon onset sowing rule: sow Kharif only when 25-30mm rain falls in 3 days and soil moisture reaches 15 cm. If onset is late >2 weeks, shift to short-duration varieties or Rabi crop.", "tags": ["season", "kharif", "monsoon", "sowing"]},

    # Phase 4 expansion: oilseeds / millets / misc cereals
    {"id": "sesame_001", "content": "Sesame is a Kharif/Zaid oilseed, 25-35C, 40-60cm rain, well-drained sandy soil pH 5.5-7.5. Major pests: capsule borer, whitefly. Diseases: phyllody (leafy outgrowth) — rogue infected plants early. Apply 50:25:25 NPK kg/ha.", "tags": ["sesame", "oilseed", "phyllody", "pest"]},
    {"id": "sunflower_001", "content": "Sunflower is a Kharif/Rabi oilseed, 20-28C. Head rot (Sclerotinia) in humid weather — spray carbendazim 0.1% at flowering. Apply 60:30:30 NPK + borax 10kg/ha for seed filling. Harvest at 115-120 days when back of head turns yellow-brown.", "tags": ["sunflower", "oilseed", "disease", "boron"]},
    {"id": "linseed_001", "content": "Linseed (flax) is a Rabi oilseed/fibre, 15-20C, 40-60cm rain. Rust and powdery mildew in humid spells — spray propiconazole 0.1% at first sign. Needs 2-3 irrigations: branching, pre-flowering and grain filling.", "tags": ["linseed", "oilseed", "rabi", "disease"]},
    {"id": "ragi_001", "content": "Finger millet (ragi) is a Kharif millet, 22-32C, 50-80cm rain. Blast and grain mold at harvest — harvest on time, sun-dry before storage. Seed rate 8-10 kg/ha with thinning at 20 DAS for uniformity.", "tags": ["ragi", "millet", "drought"]},
    {"id": "fox_001", "content": "Little millet (kodo/samai) suits drylands, 22-28C, 50-70cm rain. Shoot fly and stem borer as in sorghum. Low input: 20:20:20 NPK or FYM 5 t/ha. Mix cropping with groundnut improves soil cover.", "tags": ["millet", "kodo", "drought"]},
    {"id": "general_pest_006", "content": "Pod borer (Helicoverpa armigera): eggs on buds, larvae bore pods/ear heads. Pheromone traps 12/ha catch males. NPV 250 LE/ha or emamectin 0.4g/L at egg stage. Bird perches aid biocontrol.", "tags": ["general", "pod borer", "helicoverpa", "pest"]},
    {"id": "general_mgmt_001", "content": "Weed management: critical competition is 15-45 DAS for most Kharif crops. Pendimethalin 1.0 kg/ha pre-emergence (within 3 days of sowing) + one hand weeding at 25-30 DAS controls most annual weeds without yield loss.", "tags": ["general", "weed", "pendimethalin"]},
    {"id": "general_mgmt_002", "content": "Seed treatment basics: fungicide (thiram/carbendazim 2-3 g/kg), biofungicide (Trichoderma 4 g/kg), and Rhizobium/PSB for pulses. Treat 24h before sowing, shade-dry, sow same day. Do not mix pesticide-treated seed with feed.", "tags": ["general", "seed", "treatment", "fungicide"]},
    {"id": "storage_001", "content": "Seed storage: dry to 10-12% moisture, store in airtight double bags with neem cake or dettol leaves. Label crop, variety, year and germination %. Test germination (100 seeds in wet cloth) before sowing.", "tags": ["storage", "seed", "germination"]},
    {"id": "livestock_001", "content": "Crop-livestock integration: fodder maize/napier on bunds, crop residues as roughage, dung compost returns nutrients. One milch animal + 1 acre fodder can supply 10-15 t FYM/year and steady income in dry spells.", "tags": ["livestock", "fodder", "fym"]},

    # Phase 5 expansion: tur, jute, cashew, coconut, tea/coffee + misc
    {"id": "tur_001", "content": "Pigeonpea (tur) is a Kharif pulse, 25-35C, 60-100cm rain. Flowering is sensitive to short days — sow in June-July for full season. Pod fly and pod borer at flowering — spray emamectin 0.4g/L at 5% pod damage. Apply 20:50:20 NPK.", "tags": ["tur", "pigeonpea", "pulse", "kharif"]},
    {"id": "tur_002", "content": "Tur wilt (Fusarium) — wilted plants in patches, spread by soil. Use resistant varieties (ICP series), seed treatment with Trichoderma 4g/kg, rotate with cereals 2 years. Destroy wilted plants with roots.", "tags": ["tur", "wilt", "disease"]},
    {"id": "jute_001", "content": "Jute is a Kharif fibre, 25-35C, 120+cm rain, low-lying loamy soil. Golden mosaic and hairy caterpillar in wet spells — drain water, spray lambda-cyhalothrin 0.05% at first larvae. Retting in clean water gives quality fibre.", "tags": ["jute", "fibre", "kharif"]},
    {"id": "cashew_001", "content": "Cashew: coastal lateritic soil, 25-35C. Tea mosquito bug causes blackened nut and leaf burn — spray lambda-cyhalothrin 0.05% at flushing. Anthracnose in monsoon — spray mancozeb 0.25%. Source: ICAR cashew guidance.", "tags": ["cashew", "fruit", "pest", "disease"]},
    {"id": "coconut_001", "content": "Coconut: 27-32C, 150+cm rain, sandy to loamy. Rhinoceros beetle bores crown — remove decaying organic matter, place pheromone traps, apply 5% carbaryl in crown. Red palm weevil — pheromone traps 2/ha, fill boreholes.", "tags": ["coconut", "palm", "beetle", "weevil"]},
    {"id": "fruit_007", "content": "Fig/anji: 20-30C, well-drained soil. Fig rust in wet weather — spray streptocycline 100ppm + copper oxychloride 0.3%. Fruit fly — bait traps + emamectin on near-mature fruits. Bag fruits to prevent fly damage.", "tags": ["fig", "fruit", "rust", "fruit fly"]},
    {"id": "veg_010", "content": "Cabbage white butterfly and diamondback moth peak in winter. Release Trichogramma 50,000/ha at egg stage. Outer leaves show DBM windows — spray Bt 1g/L in evening for larvae.", "tags": ["cabbage", "moth", "biological control"]},
    {"id": "veg_011", "content": "Sweet corn/corn-on-cob: sow March-June for Zaid. Army worm and corn borer — scout weekly, spray emamectin at whorl stage. Harvest at milky stage (18-22 days after silking).", "tags": ["corn", "vegetable", "maize", "pest"]},
    {"id": "general_mgmt_003", "content": "How to spray safely: calibrate sprayer, use full-face mask and gloves, spray early morning/evening (wind <10 km/h), do not spray in flowering if bees active, wash hands after work. Never reuse pesticide containers for food/water.", "tags": ["general", "spray", "safety"]},
    {"id": "general_mgmt_004", "content": "How to read a pesticide label: crop and pest columns decide legality — the same chemical is not approved for all crops. Dose is per litre of water and per hectare. Respect pre-harvest interval (PHI) — do not harvest before days listed on label.", "tags": ["general", "label", "phi", "safety"]},
    {"id": "livestock_002", "content": "Poultry: country birds need grain + greens + shelter. Vaccinate against Ranikhet (once in 3 months). Keep chicks warm first 2 weeks (28-32C). Feed storey: 65% energy, 18-20% protein for layers.", "tags": ["livestock", "poultry", "vaccination"]},
    {"id": "soil_007", "content": "Testing soil before every season is cheapest insurance: 1 composite sample per 2 acres (15 cm depth, 10 points mixed), submit within 24h in polythene shade. Compare with last year — falling OC or K means FYM/fertilizer gap.", "tags": ["soil", "testing", "sampling"]},
    {"id": "water_006", "content": "Furrow vs flood: furrows save 25-30% water vs border flooding on slopes. Lay furrows along contour, set inflow rate so water reaches tail in 30-45 minutes. Surge irrigation saves another 10-15%.", "tags": ["water", "furrow", "efficiency"]},
    {"id": "weather_008", "content": "Pest outbreak after rain: 3-5 days of warm humid weather + broken sun increases armyworm, pod borer and blight. Scout 2x/week after every rain >20mm. Need-based spray only — calendar spraying wastes money and kills predators.", "tags": ["weather", "rain", "pest", "scouting"]},
    {"id": "market_006", "content": "How to transport to mandi: grade and clean before loading, use jute sacks (50 kg) not plastic for respiring produce, cover truck with tarpaulin, reach before 8 am for first auction. Carry weighment slip and quality note — buyers pay faster with assay.", "tags": ["market", "transport", "grading"]},
    {"id": "market_007", "content": "Storage vs sell-now decision: compare today's net (price minus transport/storage) with storage cost per quintal per day + expected spoilage. If break-even future price is above the 7-day observed trend, storing is a gamble — Kisan360 shows the threshold, not a promise.", "tags": ["market", "storage", "decision"]},
    {"id": "scheme_006", "content": "Agriculture Infrastructure Fund (AIF) gives medium-term debt for warehouses, cold stores, primary processing and post-harvest projects, with 3% interest subvention and credit guarantee. Apply via bank with DPR; state nodal officer helps with approval.", "tags": ["scheme", "aif", "infrastructure"]},
    {"id": "scheme_007", "content": "MIDH (Mission for Integrated Development of Horticulture) supports fruit orchards, hi-tech greenhouses, drip and micro-irrigation for horticulture. Subsidy is released after verification — apply on NHB/state portal before planting.", "tags": ["scheme", "midh", "horticulture"]},

    # Phase 6: crops for Maharashtra coverage + IPM depth
    {"id": "chana_001", "content": "Chana (chickpea) Rabi, 15-25C, deep black soil. Wilt at flowering — seed treatment carbendazim 2g/kg, avoid waterlogging. Pod borer at flowering — NPV 250 LE/ha twice at 10-day interval. Source: ICAR pulse package.", "tags": ["chana", "chickpea", "pulse", "wilt"]},
    {"id": "urad_003", "content": "Urad sowing: June-July Kharif, 20 kg seed/ha, row spacing 30 cm. Leaf spot in wet weather — mancozeb 0.25% at 30 and 45 DAS. Harvest when 80% pods mature; sun-dry before storage.", "tags": ["urad", "pulse", "sowing"]},
    {"id": "moong_003", "content": "Moong seed rate 20-25 kg/ha, Rhizobium 200g/10kg seed. Thrips at seedling — spinosad 0.015% at 15 DAS. Pod borer at 45-55 DAS — emamectin 0.4g/L once. Keep one protective irrigation at flowering if rain fails.", "tags": ["moong", "pulse", "pest"]},
    {"id": "groundnut_005", "content": "Groundnut pegging stage (40-50 DAS): apply gypsum 500 kg/ha, earth up to help pegs enter soil. Tikka reappears after rain — repeat mancozeb 0.2% 15 days later. Lift at 100-110 DAS when kernels are bold.", "tags": ["groundnut", "gypsum", "pegging"]},
    {"id": "soybean_001", "content": "Soybean rust (Phakopsora pachyrhizi): rust pustules on lower leaves in Aug-Sep humid spells. Spray hexaconazole 0.1% at first pustules. Use resistant varieties in late sowing.", "tags": ["soybean", "rust", "disease"]},
    {"id": "cucumber_002", "content": "Cucumber downy mildew: yellow angular spots on upper leaf, downy growth below with dew. Metalaxyl + mancozeb 0.25% at first spots. Remove badly infected leaves, avoid overhead watering.", "tags": ["cucumber", "downy mildew", "vegetable"]},
    {"id": "veg_012", "content": "Ladies finger (okra) picking: harvest every 2 days at 8-12 cm pods. Late picking makes fibrous pods. Earias fruit borer — early picking + traps; spray emamectin 1g/10L at flowering.", "tags": ["okra", "vegetable", "harvest"]},
    {"id": "veg_013", "content": "Cabbage black rot: V-shaped yellow margins with black veins. No cure — plant disease-free seedlings, rotate crucifers 2 years, chlorinate tools. Copper oxychloride 0.3% only slows spread.", "tags": ["cabbage", "black rot", "vegetable"]},
    {"id": "fruit_008", "content": "Guava: 25-35C, wilt (Fusarium) is the biggest threat — avoid planting wilted orchards, use disease-free layers, soil drench with carbendazim. Fruit fly in monsoon — bait traps, bag fruits at pea stage.", "tags": ["guava", "fruit", "wilt", "fruit fly"]},
    {"id": "fruit_009", "content": "Custard apple (sitaphal): drought-hardy, 25-35C, sandy soil. Root rot in waterlogged soil — ensure drainage. Mealybug on fruits — spray dimethoate 0.05% + remove infested fruits.", "tags": ["custard", "fruit", "mealybug"]},
    {"id": "general_mgmt_005", "content": "How to calibrate a knapsack sprayer: fill 10L water, spray on 100 sq m at field pace, measure time and refill — scale to per hectare. Wrong calibration is the top cause of poor pest control even with the right chemical.", "tags": ["general", "sprayer", "calibration"]},
    {"id": "soil_008", "content": "Green manuring: dhaincha/sunn hemp sown June, cut and incorporated at 45 days. Adds 50-80 kg N/ha and 5-8 t biomass. Needs 3-4 weeks to decompose before Rabi sowing — plan ahead.", "tags": ["soil", "green manure", "dhaincha"]},

    # Phase 7: FPO, groundwater, mechanization (Maharashtra demo depth)
    {"id": "market_008", "content": "FPO decision checklist: compare pooled net vs individual net, check working capital and advance terms, insist on written pool price date, understand quantity cap and grading. A pool that beats the mandi on paper but pays 60 days late may be worse in cash terms.", "tags": ["market", "fpo", "decision"]},
    {"id": "water_007", "content": "Groundwater budgeting: if wells fall >2 m in a season, reduce water-intensive area next year. Drip on sugarcane and vegetables cuts pumping hours 30-40%. Log hours run per acre to see the true cost per quintal.", "tags": ["water", "groundwater", "budget"]},
    {"id": "general_mgmt_006", "content": "Custom hiring centres: rent tractors, harvesters and sprayers instead of owning. Check readiness (fuel, driver, labour), agree on per-hour vs per-acre billing before work, and note field time — disputes are cheaper to avoid than to settle.", "tags": ["general", "mechanization", "custom"]},
    {"id": "soil_009", "content": "Subsoiling (chisel plough 35-40 cm) every 2-3 years breaks hardpan on vertisols, lets roots reach moisture. Do it once in dry summer, not every season — it can dry the profile if done late.", "tags": ["soil", "subsoiling", "vertisol"]},
    {"id": "market_009", "content": "Reading arrival reports: high arrivals + falling modal means supply pressure; low arrivals + firm modal means tight supply. Kisan360 describes observed trends only — never will it convert an arrival spike into a price prediction.", "tags": ["market", "arrivals", "trend"]},
    {"id": "general_mgmt_007", "content": "Record book minimum: date, crop, input (dose, cost), rain (mm), irrigation (hours), pest observed, spray (chemical, dose). Two seasons of this book beat any app recommendation for your field.", "tags": ["general", "record", "farm"]},
    {"id": "livestock_003", "content": "Goat farming in dry Maharashtra: Black Bengal / Osmanabadi breeds, 10-20 animals on 1 acre forage + crop residue. Vaccinate against enterotoxaemia and PPR yearly. Housing on slatted floor keeps animals dry in monsoon.", "tags": ["livestock", "goat", "vaccination"]},
    {"id": "dairy_001", "content": "Dairy: green fodder (napier, maize, sorghum) must be 60% of ration. Mineral mixture 50g/day keeps calcium/phosphorus in balance. Cool milk quickly, sell through co-op for graded price and prompt payment.", "tags": ["dairy", "fodder", "mineral"]},

    # Phase 10: IPM depth + minor crops
    {"id": "cotton_006", "content": "Cotton mealybug (Phenacoccus solenopsis): cottony masses on stems and bolls. Remove infested parts, spray dimethoate 0.05% at early stage. Avoid excess N that flushes soft growth mealybug loves.", "tags": ["cotton", "mealybug", "pest"]},
    {"id": "sugarcane_005", "content": "Sugarcane scale insects (Melanaspis) in dry hardlands — scrape soft scales, spray dimethoate 0.1% + sticker. Detrashing (remove old dry leaves) improves air flow and reduces borer hiding.", "tags": ["sugarcane", "scale", "pest"]},
    {"id": "rice_009", "content": "Rice seed rate and nursery: 20 kg/ha seed, nursery on 100 sq m with 4 kg seed per 100 sq m of main field. Pull seedlings at 25-30 DAS with roots intact. SRI extras: 12 kg/ha seed, wide spacing, alternate wetting and drying.", "tags": ["rice", "nursery", "sri"]},
    {"id": "wheat_007", "content": "Wheat sowing: 100-125 kg/ha seed (HYV), row spacing 20-22.5 cm, depth 4-5 cm. Zero tillage needs full P+K basal + first N at sowing. Watch terminal heat (35C+ at grain fill) — early sowing avoids it.", "tags": ["wheat", "sowing", "zero till"]},
    {"id": "tomato_002", "content": "Tomato staking for processing types reduces fruit rot 20-30%. Mulch with straw to keep soil splash off leaves in monsoon. Determinate varieties for once-over harvest; indeterminate for continuous picking.", "tags": ["tomato", "staking", "mulch"]},
    {"id": "general_mgmt_008", "content": "Trap crops: castor (2 rows) attracts Spodoptera from maize/groundnut; mustard attracts Lipaphis. Remove and destroy the trap crop after pests collect on it — do not harvest it for grain.", "tags": ["general", "trap crop", "ipm"]},
    {"id": "dairy_002", "content": "Chaff cutter economics: chopped fodder wastes 20-30% less than whole. Cut straw and green fodder to 3-4 cm before feeding. Mix 60% green + 40% dry roughage for better digestion.", "tags": ["dairy", "fodder", "chaff"]},
    {"id": "poultry_002", "content": "Broiler house: 1 sq ft per bird to 6 weeks, litter of paddy husk 3 inches deep, brooder 32C week 1 falling 2C per week. Newcastle vaccine by eye-drop at 7 and 21 days.", "tags": ["poultry", "broiler", "vaccination"]},
    {"id": "solar_001", "content": "Solar pump sizing: 5 HP ≈ 1.5-2 acres drip in kharif (Maharashtra). Panels on south-facing structure, shadow-free. Net metering — export surplus in summer, import in monsoon. Service via state solar nodal agency.", "tags": ["solar", "pump", "drip"]},
    {"id": "market_010", "content": "Quality premium: graded (A) lots quote above modal; ungraded lots below. If grading cost is Rs 30-50/q and premium is Rs 150+/q, grading pays. Photo-grade via Kisan360 before transport.", "tags": ["market", "grading", "premium"]},
    {"id": "soil_010", "content": "Phosphorus fix in calcareous soils: band-place DAP below seed rather than broadcast. Mix FYM/PM in the band — organic acids release fixed P for 20-30 days.", "tags": ["soil", "phosphorus", "band"]},
    {"id": "water_008", "content": "Pond budgeting: 1 hectare pond (100x100 m) in 800mm rainfall area collects ~6-8 lakh litres. Use it for 2 protective irrigations (50mm each) on 1 ha. Desilt every 2 years.", "tags": ["water", "pond", "budget"]},

    # Phase 11: remaining millets, pulses, minor crops (~200 total)
    {"id": "kodo_001", "content": "Kodo millet (varai) is a drought millet, 22-30C, 50-80cm rain. Grain mold at harvest in humid spell — harvest at 110 days, dry to 12% moisture. Low input: FYM 5 t/ha + 30:20:0 NPK. Mix with pulses for soil cover.", "tags": ["kodo", "millet", "drought"]},
    {"id": "kutki_001", "content": "Little millet (kutki) is a Kharif upland millet, 22-28C. Shoot fly — early sowing and 2% neem spray at 15 DAS. Weeding at 25 DAS decides yield more than fertilizer on these lands.", "tags": ["little millet", "kutki", "shoot fly"]},
    {"id": "barley_002", "content": "Barley sowing: mid-October, 75-100 kg/ha seed, 20 cm rows. First irrigation at crown root (21 DAS). Aphid threshold 5-10/tiller — dimethoate 0.05% once. Harvest at 110-120 DAS.", "tags": ["barley", "sowing", "aphid"]},
    {"id": "oats_001", "content": "Oats are a Rabi fodder/grain, 15-20C. Crown rust in warm humid spells — propiconazole 0.1% at first pustules. For fodder cut at 60-70 DAS; for grain allow full maturity.", "tags": ["oats", "fodder", "rust"]},
    {"id": "tur_003", "content": "Tur harvest: pick when pods turn grey-yellow (150-160 DAS). Thresh and winnow same week — delay invites bruchids in storage. Store with neem leaves 2% weight.", "tags": ["tur", "harvest", "storage"]},
    {"id": "chana_002", "content": "Chana picking: pods yellow-brown, grain at 12% moisture. Over-ripe chana shatters on threshing. Bleach-green separation: pick twice for uniform maturity.", "tags": ["chana", "harvest"]},
    {"id": "mung_004", "content": "Moong harvest: 60-75 days Kharif. Pick ripe pods in 2-3 rounds — waiting for all pods blackens harvested grain. Sun-dry 2 days before threshing.", "tags": ["moong", "harvest"]},
    {"id": "sesame_002", "content": "Sesame harvest: leave yellows at 90-100 DAS. Stack and thresh when capsules dry. Shattering on delay — harvest in the morning when dew softens pods.", "tags": ["sesame", "harvest"]},
    {"id": "groundnut_006", "content": "Groundnut curing: lift at 100-110 DAS, windrow 2 days, strip pods, sun-dry in shade to 10% shell moisture. Store pods in gunny with neem cake — shelled kernels go rancid in 3 months.", "tags": ["groundnut", "curing", "storage"]},
    {"id": "veg_014", "content": "Bitter gourd: Zaid, 25-32C, pandal training. Fruit fly is the top loss — bait traps + early picking at 15 cm. Powdery mildew at full vine — sulfur 0.2% every 10 days.", "tags": ["bitter gourd", "fruit fly"]},
    {"id": "veg_015", "content": "Pumpkin: Zaid/Kharif, 20-30C, sprawling. Powdery mildew races on leaves in monsoon — spray sulfur 0.2% at first white patches. Vine borer: cut and destroy bored vines.", "tags": ["pumpkin", "powdery mildew"]},
    {"id": "veg_016", "content": "Beans (French): 15-25C Rabi. Anthracnose in wet weather — carbendazim 0.1% at first spots. Bean aphid at flowering — imidacloprid 0.05% at 5/tiller threshold.", "tags": ["bean", "anthracnose", "aphid"]},
    {"id": "fruit_010", "content": "Litchi: 25-30C, needs 100+ chill hours for flowering. Fruit cracking after rain — keep soil moisture even, mulch root zone. Fruit bat damage at ripening — night netting is the only sure protection.", "tags": ["litchi", "cracking", "fruit bat"]},
    {"id": "fruit_011", "content": "Watermelon: Zaid, 25-35C, sandy loam. Downy mildew and fruit fly peak at fruit set. Check ripeness by tendril drying + hollow sound. Never use carbide for ripening — use ethylene/ethephon per label.", "tags": ["watermelon", "fruit fly", "ripening"]},
    {"id": "general_mgmt_009", "content": "Honeybee on mustard: 2-3 boxes/ha doubles seed set. Keep 50 m from insecticide-sprayed fields during flowering, spray in evening only. Income from honey roughly equals seed value.", "tags": ["general", "bee", "mustard"]},
    {"id": "soil_011", "content": "Gypsum on sodic soil: 5-10 t/ha worked in, then leach with 2-3 floodings. Follow with green manure + tolerant crop (rice/barley) for one season before returning to sensitive crops.", "tags": ["soil", "sodic", "gypsum"]},
    {"id": "water_009", "content": "Borewell economics: log pumping hours vs area irrigated. If hours/acre rise >20% year-on-year with same crop, water table is falling — shift area to drip, pulses and oilseeds next year.", "tags": ["water", "borewell", "budget"]},
    {"id": "livestock_004", "content": "Sheep: 10-15 ewes on common grazing + crop residue needs 30-40 g mineral daily. Vaccinate against enterotoxaemia yearly. Housing floor raised 1 ft keeps animals dry.", "tags": ["livestock", "sheep", "vaccination"]},

    # Phase 17: pest cycles + soil + water depth
    {"id": "pest_cycle_001", "content": "Whitefly population builds 3 weeks after first rains. Yellow traps at field edges catch founders before they enter. Delay in vector control multiplies leaf curl and mosaic losses 3-5x.", "tags": ["pest", "whitefly", "cycle"]},
    {"id": "pest_cycle_002", "content": "Armyworm (Spodoptera) is a monsoon pest that strips maize, sorghum, soybean and groundnut in 7-10 days. Scout whorls after moth traps catch males. Emamectin on young larvae beats older larvae that hide in whorl.", "tags": ["pest", "armyworm", "spodoptera"]},
    {"id": "soil_012", "content": "Boron in black soils: apply borax 10 kg/ha at flower initiation for cotton, sunflower, cauliflower. Excess boron is toxic — use soil test dose, not calendar dose. Foliar 0.1% borax for quick correction in standing crop.", "tags": ["soil", "boron", "cotton"]},
    {"id": "soil_013", "content": "Zinc in calcareous black soils: ZnSO4 25 kg/ha in soil, or 0.5% ZnSO4 foliar at 2-3 leaves. Interveinal chlorosis on young leaves is the field sign. Mix with well-decomposed FYM for better uptake.", "tags": ["soil", "zinc", "foliar"]},
    {"id": "water_010", "content": "Alternate wetting and drying (AWD) in rice: irrigate when water falls 2 cm below the surface, re-flood to 2 cm. Saves 25% water, cuts methane, and hardens roots. Use a marked bamboo stick to track.", "tags": ["water", "rice", "awd"]},
    {"id": "water_011", "content": "Mulch economics: 10 cm straw mulch costs roughly 1 irrigation saved per 3 weeks in summer. It also keeps roots 2-3C cooler. For vegetables, plastic mulch 25 micron pays back in 1 season via earliness.", "tags": ["water", "mulch", "plastic"]},
    {"id": "general_mgmt_010", "content": "Fallow health: a 3-week weed-free fallow before Kharif sowing cuts first-flush weed flush by half. Plough shallow (8 cm) after first rain to germinate and kill that flush before main sowing.", "tags": ["general", "fallow", "weed"]},
    {"id": "livestock_005", "content": "Mineral mixture portal: salt, dicalcium phosphate, magnesium, zinc, copper, manganese, cobalt, iodine, vitamins A/D/E. 50 g/day for milch animals. Simple salt alone is not mineral supplementation.", "tags": ["livestock", "mineral", "dairy"]},
    {"id": "hort_001", "content": "Micro-grafting and air layering are the fastest way to multiply elite fruit plants: guava, lemon, fig. Use 1-year wood, rooting hormone, and shade 50%. Provides true-to-type plants.", "tags": ["horticulture", "propagation"]},
    {"id": "market_011", "content": "Grade before you transport: sorting by size and colour takes 2 hours for 10 q and can add Rs 100-200/q premium. Unsorted lots take the lowest grade price in the auction ring.", "tags": ["market", "grading", "premium"]},

    # Phase 19: final push (~200 docs)
    {"id": "maize_006", "content": "Maize detasseling for hybrids: remove tassels before pollen shed in female rows. Keep male:female ratio 1:3. Irrigate at silk stage — moisture stress here cuts kernels per ear 30%.", "tags": ["maize", "hybrid", "detasseling"]},
    {"id": "wheat_008", "content": "Wheat straw for fodder vs incorporation: incorporating 4-5 t/ha straw + 20 kg N/ha adds 25-30 kg N equivalent over next season. Burning loses carbon the soil needs — chopper + inoculant is the alternative.", "tags": ["wheat", "straw", "carbon"]},
    {"id": "rice_010", "content": "Rice direct-seeded (DSR) vs puddled: DSR saves 20-30% water, 10 days labour, matures 7 days earlier. Uses 25 kg/ha seed at 20x10 cm. Weed control needs pendimethalin + one weeding.", "tags": ["rice", "dsr", "direct"]},
    {"id": "onion_004", "content": "Onion grading: separate by size (45mm+, 35-45, <35) and colour. Graded big onions quote Rs 100-300/q above ungraded in Lasalgaon auction. Photo-grade before transport if you can.", "tags": ["onion", "grading", "premium"]},
    {"id": "potato_002", "content": "Potato seed: certified seed potato 40-50 g tubers, cut and cured 1 day, treat mancozeb 0.2% slurry. Store in dark, ventilated, 8-12C. Do not use ware potatoes as seed — virus builds silently.", "tags": ["potato", "seed", "storage"]},
    {"id": "veg_017", "content": "Bristle/eggplant staking and mulching: reduces fruit borer contact with soil. Pick every 3 days at glossy stage — overripe fruits stop new fruiting. Drip + mulch doubles early yield.", "tags": ["brinjal", "mulch", "harvest"]},
    {"id": "veg_018", "content": "Cabbage sequential harvest: take outer leaves weekly for market while plant feeds in field. Adds 3-4 extra pickings vs single cut. Good where labour is daily but area is small.", "tags": ["cabbage", "sequential"]},
    {"id": "fruit_012", "content": "Guava training: modified leader (3-4 branches). Prune after harvest to 1/3 canopy for next flush. Tipping at 60 cm spreads canopy and fruit count by 20%.", "tags": ["guava", "pruning"]},
    {"id": "soil_014", "content": "Contamination test: if pesticide container leaks into pond, chlorinate 50 ppm 24h, remove sludge, do not irrigate vegetables for 7 days. Test with extension officer before resuming.", "tags": ["soil", "pond", "safety"]},
    {"id": "water_012", "content": "Borewell pump matching: 0.5 HP lifts ≈ 6-8 lakh litres/day at 30 m suction. Run in early morning when voltage stable. Log start/stop hours — the log is your water bill.", "tags": ["water", "pump", "hours"]},
    {"id": "general_mgmt_011", "content": "Extension officer bridge: take a photo + market card + soil report to the officer — three facts beat ten questions. Ask for the district package, not a general lecture.", "tags": ["general", "extension"]},
    {"id": "market_012", "content": "Timing arrivals: morning arrival (before 9 am) catches the first auction where traders bid hottest. Evening arrival takes whatever is left. Plan transport the night before.", "tags": ["market", "arrival", "timing"]},

    # Phase 23: harvest + storage depth
    {"id": "harvest_001", "content": "Mobile harvester hiring: book 2 weeks ahead at peak season, keep a spare engine and belt list. Harvest at physiological maturity — delayed harvest loses 5-10% grain to shattering and birds.", "tags": ["harvest", "harvester", "machinery"]},
    {"id": "harvest_002", "content": "Winnowing wind: 3-4 m/s at 1.5 m height separates grain from chaff. Clean floor, 2-3 turnings, then bag. Storage without winnowing invites weevils within 30 days.", "tags": ["harvest", "winnowing", "storage"]},
    {"id": "storage_002", "content": "Pulse storage: dry to 10% moisture, add 5% neem powder or 500g alum per 100kg. Tightly sealed bins beat gunny bags — weevils thrive in loose sacks.", "tags": ["storage", "pulse", "weevil"]},
    {"id": "storage_003", "content": "Vegetable grading line: 3 tiers (extra, marketable, cull). Cull is compost, not market. Grading at farm gate saves 1 mandi trip and lifts average price 10-15%.", "tags": ["storage", "vegetable", "grading"]},
    {"id": "soil_015", "content": "Compost pit: 1.5m x 1m x 1m, layers of dung + straw + soil, water weekly, covered with polythene. Ready in 90 days when dark and crumbly. Turn every 3 weeks for air.", "tags": ["soil", "compost"]},
    {"id": "general_mgmt_012", "content": "Farm diary economics: last season's notes predict this season's pest dates within ±7 days. Write sowing, rain, pest, spray and price on one page — it is your best advisory source after 2 years.", "tags": ["general", "diary", "record"]},

    # Phase 24: final push (~235)
    {"id": "soil_016", "content": "Gypsum in vertisols improves infiltration from 5 to 15 cm/hr. Apply 2 t/ha once, not every year. It also supplies calcium for groundnut pegging and reduces crusting at emergence.", "tags": ["soil", "gypsum", "vertisol"]},
    {"id": "soil_017", "content": "Tank silt (pond/desilt) at 20 t/ha brightens tired soils. Apply in summer, mix shallow. It brings clay and organic carbon poor soils lack — test salts first if from brackish tank.", "tags": ["soil", "silt", "tank"]},
    {"id": "water_013", "content": "Sprinkler at 3.5 kg/cm2 gives uniform 10-12 mm irrigation for wheat and pulses. Night operation saves 20% evaporation. Don't run in wind above 15 km/h — drift wastes water.", "tags": ["water", "sprinkler", "wind"]},
    {"id": "water_014", "content": "Drip lateral flushing weekly: open end cap 2 minutes to clear emitters before clogging. Acid treatment (1:1000 HNO3) dissolves carbonate scale. Budget 30 minutes per hectare per week.", "tags": ["water", "drip", "flushing"]},
    {"id": "fert_007", "content": "Urea vs neem-coated urea on same field: NCU needs 10 days lead time and loses 10-15% less nitrogen in first 30 days. In wet Kharif the saving is larger; in dry Rabi it is smaller.", "tags": ["fertilizer", "ncu", "urea"]},
    {"id": "fert_008", "content": "Single super phosphate (SSP) is 16% P + 11% S + Ca. On S-deficient soils it beats DAP even at same P. Band place near roots for early uptake.", "tags": ["fertilizer", "ssp", "sulfur"]},
    {"id": "general_mgmt_013", "content": "Border bund maintenance: repair rat holes in bunds before monsoon or stored rainwater leaks. A 20 cm bund with 30 cm base holds most one-season showers.", "tags": ["general", "bund", "rainwater"]},
    {"id": "market_013", "content": "Mandi vs farmgate choice: farmgate saves transport but takes 5-10% less. If your lot is under 10 q and trader comes to your village, farmgate may net more after transport. If above 20 q, the mandi edge usually wins.", "tags": ["market", "farmgate", "transport"]},
    {"id": "dairy_003", "content": "Mastitis check: 3% strip cup each evening catches early flakes. Teat dip (0.1% iodine) after milking halves new infections. Culled milk never enters the can supply.", "tags": ["dairy", "mastitis", "teat"]},
    {"id": "poultry_003", "content": "Duck rearing: Khaki Campbell lays 280 eggs/year on paddy stubble. Night shelter 2 sq ft/bird, daytime free range. Vaccinate Duck plague (annually) and follow 2-2-1 feed.", "tags": ["poultry", "duck", "eggs"]},
    {"id": "hort_002", "content": "Raised beds for vegetables in low-lying plots: 30 cm height, 1.2 m wide, drains in monsoon. Same soil, two extra pickings in wet years. Mulch between beds to stop splash.", "tags": ["horticulture", "raised bed", "vegetable"]},
    {"id": "market_014", "content": "Price slip record: note crop, date, mandi, modal, transport paid — every sale. After one season you know your true net per quintal, not the headline. That sheet beats any market tip.", "tags": ["market", "record", "slip"]},

    # Phase 26: market risk + record-keeping
    {"id": "market_015", "content": "Price risk rule: never borrow against an expected price. If loan repayment needs Rs X/q, sell enough at harvest to cover it and speculate only with the surplus. Kisan360 shows break-even — decide how much is ‘surplus’ yourself.", "tags": ["market", "risk", "debt"]},
    {"id": "market_016", "content": "Arrival timing around festivals: demand for onion and banana spikes before festivals. Arriving 3-4 days early, graded and cleaned, catches the spike; arriving on the festival day takes the leftover price.", "tags": ["market", "festival", "timing"]},
    {"id": "general_mgmt_014", "content": "Input receipt file: staple bills by crop-season. In 2 seasons you will see which input actually moved yield — the most reliable agronomy data you will ever own.", "tags": ["general", "record", "input"]},
    {"id": "soil_018", "content": "FYM quality test: dark, crumbly, earthy smell without ammonia. If it smells like ammonia or shows white patches of urea, it is half-baked — cure 2 more weeks before field use.", "tags": ["soil", "fym", "compost"]},

    # Phase 27: final 250 push
    {"id": "hort_003", "content": "Potted fruit on balcony: lemon, chilli, tomato in 12-inch pots, cocopeat + FYM 50:50. Water daily in summer. This is a learning plot — not a substitute for field advice on micro-nutrients.", "tags": ["horticulture", "pot", "home"]},
    {"id": "hort_004", "content": "Grafting season: mango and guava graft in monsoon, lemon in winter, rose in spring. Scions should be pencil-thick, 1-year wood, disease-free. Tape tightly, shade 50%, mist daily.", "tags": ["horticulture", "grafting"]},
    {"id": "soil_019", "content": "Calcareous soil fixing phosphorus: use 60% P as DAP band + 40% as SSP with FYM. Broadcast DAP on such soils wastes 30% of the dose in 2 weeks.", "tags": ["soil", "phosphorus", "calcareous"]},
    {"id": "water_015", "content": "Check valve on borewell prevents water hammer and column fall. Cost Rs 500-800, saves a pump repair every 2-3 years. Install at pump mouth, not at tap.", "tags": ["water", "pump", "check valve"]},
    {"id": "fert_009", "content": "Potash in banana and potato: MOP (0-0-60) at 100 kg/ha in 2 splits. Green manuring does not replace potash on depleted soils — test before assuming.", "tags": ["fertilizer", "potash", "banana"]},
    {"id": "general_mgmt_015", "content": "Seed village model: one farmer per village multiplies own crop seed (treated, graded, tagged). Earns 20-30% over market price and raises village seed quality year by year.", "tags": ["general", "seed", "village"]},
    {"id": "market_017", "content": "eNAM auction discipline: bid boxes close at fixed time — early quality photos and 60 kg samples get better opening bids. Unsampled lots take the lowest band.", "tags": ["market", "enam", "auction"]},
    {"id": "market_018", "content": "Storage receipt: pledge stored produce for 60-75% loan at NABARD warehouse rate. Cheaper than moneylender 3%/month. WDRA warehouses are registered — check the list.", "tags": ["market", "warehouse", "pledge"]},
    {"id": "pest_001", "content": "Economic threshold thinking: spray only when insects cross damage equal to spray cost. Below threshold they are not pests — they are free pest-food for predators.", "tags": ["pest", "threshold", "ipm"]},
    {"id": "pest_002", "content": "Phoring trap glow: yellow (aphid/thrips) + blue (thrips) + pheromone (bollworm) 3 types cover 80% of flying pests. Replace sticky cards weekly. Count insects to decide if spray is needed at all.", "tags": ["pest", "trap", "monitoring"]},
    {"id": "dairy_004", "content": "Calving interval matters more than yield per day: a cow calving every 15 months beats a high-yielder at 20 months in lifetime profit. Track days open — minimising them is dairy’s cheapest gain.", "tags": ["dairy", "calving"]},

    # Government schemes (factual, verify on official portal)
    {"id": "scheme_001", "content": "PM-KISAN (Pradhan Mantri Kisan Samman Nidhi) provides Rs 6,000 per year to eligible farmer families in three Rs 2,000 installments (April, August, December) via DBT. Eligibility depends on land records and government rules. Verify status on pmkisan.gov.in.", "tags": ["scheme", "pm-kisan", "income", "dbt"]},
    {"id": "scheme_002", "content": "PMFBY (Pradhan Mantri Fasal Bima Yojana) is crop insurance for notified crops against natural calamities, pests and diseases. Farmers pay a notified premium (capped by crop category); claims follow official crop-cutting and weather-trigger rules. Enrolment window and cut-off dates vary by season and state.", "tags": ["scheme", "pmfby", "insurance", "crop"]},
    {"id": "scheme_003", "content": "Kisan Credit Card (KCC) gives short-term crop credit and working capital through banks with interest subvention on prompt repayment of the crop loan. Loan limit and documents depend on bank, crop, land record and state rules. Apply via your bank or CSC.", "tags": ["scheme", "kcc", "credit", "bank"]},
    {"id": "scheme_004", "content": "Soil Health Card reports soil pH, EC, organic carbon, N-P-K and micronutrients from a lab test of a sample collected at 15 cm depth. Use it to set fertilizer doses with your extension officer. Retest every 2-3 years.", "tags": ["scheme", "soil health card", "fertilizer", "testing"]},
    {"id": "scheme_005", "content": "PMKSY (Pradhan Mantri Krishi Sinchayee Yojana) supports micro-irrigation such as drip and sprinkler and water-use efficiency at farm level. Subsidy rate and eligible works vary by state guideline. Check the state agriculture portal before ordering equipment.", "tags": ["scheme", "pmksy", "irrigation", "drip", "sprinkler"]},
]

